 }
 const label=document.createElement("label");label.htmlFor="pokemonSpecialEvent-"+p.id;label.textContent="Special Event";
 const select=document.createElement("select");select.id=label.htmlFor;
 for(const event of specialEvents){
   const inEvent=specialEventPokemonHas(event.slug,catalogSlug);
   select.add(new Option(`${event.name||event.slug} • ${event.enabled?"LIVE":"OFF"}${inEvent?" • Added":""}`,event.slug));
